return $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      domain: r.domain || '',
      status: r.status || '',
      emails: (r.emails || []).map(e => e.email).join(', '),
      phones: (r.phones || []).map(p => p.e164 || p.raw).join(', '),
      socials: (r.socials || []).map(s => s.url).join(', '),
      enriched_at: new Date().toISOString()
    }
  };
});
